import { useNavigate } from "react-router-dom";

export default function PasswordResetSuccessPage() {
  const navigate = useNavigate();

  return (
    <div className="min-h-screen bg-cream flex items-center justify-center px-6">
      <div className="bg-white rounded-2xl border border-gray-200 p-10 w-full max-w-sm text-center">
        <div className="w-14 h-14 bg-gray-100 rounded-full flex items-center justify-center text-green-600 text-2xl mx-auto mb-5">
          ✓
        </div>
        <h1 className="font-serif text-3xl font-normal mb-3">Password Reset!</h1>
        <p className="text-sm text-gray-500 leading-relaxed mb-7">
          Your password has been successfully reset. You can now sign in to your account with your new password.
        </p>
        <button
          className="w-full py-3.5 bg-red text-white rounded-full text-sm font-medium hover:bg-red-dark transition-all"
          onClick={() => navigate("/sign-in")}
        >
          Back to Sign In →
        </button>
        <p className="text-xs text-gray-300 mt-5">For security, all other sessions have been logged out.</p>
      </div>
    </div>
  );
}
